class beach {
  char padding[0x2B8]; vector3d travel_distance; beach_object *my_objects;
  int current_breakmap; int num_breakmap; void *smashedEntity;
  struct { IconChallenge *icon; PhotoChallenge *photo; } challenges;
public: void reset();
};
void beach::reset ()
{
  beach_object *tmp;
  for (tmp = my_objects; tmp != 0; tmp = tmp->next) {
    if (tmp->spawned) tmp->despawn ();
    tmp->times_spawned = 0;
  }
  for (beach_object *fobj = my_objects; fobj != 0; fobj = fobj->next)
    fobj->active = ((fobj->timer_type == current_breakmap) || (fobj->timer_type == -1));
  travel_distance = ZEROVEC;
  current_player_info.ClearAccomplishments();
  if (challenges.icon) challenges.icon->Retry();
  if (challenges.photo) challenges.photo->Retry();
  if(g_game_ptr->get_game_mode() == 0 &&
     os_developer_options::inst()->is_flagged(os_developer_options::FLAG_E3_BUILD))
    g_career->ClearAllGoals();
  if (g_game_ptr->get_game_mode() == 0)
    g_career->StartNewRun();
}
